using System;
using System.IO;
using System.Linq;
using System.Reflection;
using Newtonsoft.Json.Linq;
using HollowCraft.Standalone;

internal static partial class Program
{
    private static NativeRoom CurrentRoom(NativeGame game)=>(NativeRoom)typeof(NativeGame).GetProperty("Room",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(game);
    private static void Advance(NativeGame game,int ticks){for(int i=0;i<ticks;i++)game.Pump(.05);}
    private static void Put(NativeRoom room,int x,int y,string id){room.Blocks[NativeRoom.Key(x,y)]=NativeRoom.Cell(x,y,id);}
    private static NativeGame WorldCase(string root,string assets,string name) {var game=new NativeGame(Path.Combine(root,"world-migration"),assets);Send(game,"world",name,"scene","exactX",5,"exactY",1);Latest(game);return game;}
    private static void WorldMigration(string root,string assets) {
        using(var game=WorldCase(root,assets,"water")){var r=CurrentRoom(game);for(int i=-10;i<11;i++)Put(r,i,0,"stone");Put(r,-1,1,"water");Put(r,1,1,"water");Advance(game,10);Check((bool?)r.Blocks["0:1"]["source"]==true,"Two neighboring water sources renew a supported source");Check(r.Blocks["-1:1"]["source"].Value<bool>(),"Fluid updates preserve original source identity");}
        using(var game=WorldCase(root,assets,"recede")){var r=CurrentRoom(game);for(int i=-10;i<11;i++)Put(r,i,0,"stone");Put(r,0,3,"water");Advance(game,30);Check(r.Blocks.TryGetValue("0:2",out var fall)&&(bool?)fall["falling"]==true,"Water descends as a falling column");Check(r.Blocks.Values.Any(c=>(string)c["id"]=="minecraft:water"&&(int)c["x"]!=0),"Water spreads from a supported column");r.Blocks.Remove("0:3");Advance(game,160);Check(!r.Blocks.Values.Any(c=>(string)c["id"]=="minecraft:water"),"Removing the last source makes all connected flows recede");}
        using(var game=WorldCase(root,assets,"lava")){var r=CurrentRoom(game);Put(r,0,3,"lava");Advance(game,10);Check(!r.Blocks.ContainsKey("0:2"),"Lava does not update at water speed");Advance(game,25);Check(r.Blocks.ContainsKey("0:2"),"Lava advances on its 30 tick clock");Put(r,1,3,"water");Advance(game,5);Check((string)r.Blocks["0:3"]["id"]=="minecraft:obsidian","Water hardens a lava source into obsidian");}
        using(var game=WorldCase(root,assets,"stone-generator")){var r=CurrentRoom(game);Put(r,0,3,"lava");Put(r,0,2,"water");Advance(game,5);Check((string)r.Blocks["0:2"]["id"]=="minecraft:stone","Downward lava entering water makes stone");}
        using(var game=WorldCase(root,assets,"sponge")){var r=CurrentRoom(game);Put(r,0,1,"sponge");for(int i=-4;i<=4;i++)if(i!=0)Put(r,i,1,"water");Advance(game,5);Check((string)r.Blocks["0:1"]["id"]=="minecraft:wet_sponge"&&!r.Blocks.ContainsKey("1:1"),"Sponge absorbs adjacent water and becomes wet");}
        using(var game=WorldCase(root,assets,"wire")){var r=CurrentRoom(game);Put(r,-1,1,"redstone_block");for(int i=0;i<5;i++)Put(r,i,1,"redstone");Advance(game,1);for(int i=0;i<5;i++)Check((int)r.Blocks[i+":1"]["power"]==15-i,"Dust attenuates one level per wire: "+i);r.Blocks.Remove("-1:1");Advance(game,2);Check(r.Blocks.Values.All(c=>(int?)c["power"]==0),"Wire cannot keep itself powered after its source is removed");}
        using(var game=WorldCase(root,assets,"repeater")){var r=CurrentRoom(game);Put(r,-1,1,"redstone_block");Put(r,0,1,"repeater");r.Blocks["0:1"]["delay"]=4;Put(r,1,1,"redstone");Advance(game,2);Check((int?)r.Blocks["0:1"]["power"]!=15&&(int?)r.Blocks["1:1"]["power"]!=15,"Repeater waits for its configured delay");Advance(game,8);Check((int)r.Blocks["0:1"]["power"]==15&&(int)r.Blocks["1:1"]["power"]==15,"Repeater restores full signal in its output direction");r.Blocks.Remove("-1:1");Advance(game,10);Check((int)r.Blocks["0:1"]["power"]==0,"Repeater turns off after its falling edge delay");}
        using(var game=WorldCase(root,assets,"observer")){var r=CurrentRoom(game);Put(r,0,1,"observer");Put(r,1,1,"stone");Advance(game,1);Put(r,1,1,"cobblestone");Advance(game,1);Check((bool?)r.Blocks["0:1"]["powered"]!=true,"Observer schedules instead of firing in the same tick");Advance(game,2);Check((bool?)r.Blocks["0:1"]["powered"]==true,"Observer emits a delayed pulse for a state change");Advance(game,2);Check((bool?)r.Blocks["0:1"]["powered"]==false,"Observer pulse ends after two ticks");}
        using(var game=WorldCase(root,assets,"piston")){var r=CurrentRoom(game);Put(r,0,1,"sticky_piston");Put(r,1,1,"cobblestone");Put(r,0,0,"redstone_block");Advance(game,1);Check((bool?)r.Blocks["0:1"]["extended"]==true&&(string)r.Blocks["2:1"]["id"]=="minecraft:cobblestone","Powered piston pushes its line once");r.Blocks.Remove("0:0");Advance(game,1);Check((string)r.Blocks["1:1"]["id"]=="minecraft:cobblestone"&&!r.Blocks.ContainsKey("2:1"),"Sticky piston pulls the front block back on retraction");Put(r,1,1,"bedrock");Put(r,0,0,"redstone_block");Advance(game,1);Check((bool?)r.Blocks["0:1"]["extended"]!=true&&(string)r.Blocks["1:1"]["id"]=="minecraft:bedrock","Bedrock prevents the whole piston transaction");}
        using(var game=WorldCase(root,assets,"hopper")){var r=CurrentRoom(game);Put(r,0,1,"hopper");Put(r,0,0,"chest");r.Containers["0:1"]=new NativeContainer("minecraft:hopper",5);r.Containers["0:1"].Slots[0]=NativeStack.New("diamond",3);Advance(game,24);Check(r.Containers["0:0"].Slots.Sum(s=>s.Id=="minecraft:diamond"?s.Count:0)==3&&r.Containers["0:1"].Slots.All(s=>s.Empty),"Hopper moves exactly one item per cooldown without copies");Put(r,1,1,"redstone_block");r.Containers["0:1"].Slots[0]=NativeStack.New("diamond",3);Advance(game,16);Check(r.Containers["0:1"].Slots[0].Count==3,"Powered hopper stops item transfer");}
        using(var game=WorldCase(root,assets,"dropper")){var r=CurrentRoom(game);Put(r,0,1,"dropper");Put(r,1,1,"chest");r.Containers["0:1"]=new NativeContainer("minecraft:dropper",9);r.Containers["0:1"].Slots[0]=NativeStack.New("diamond",5);Put(r,-1,1,"redstone_block");Advance(game,12);Check(r.Containers["1:1"].Slots[0].Count==1&&r.Containers["0:1"].Slots[0].Count==4,"Dropper transfers once per rising edge, not continuously");}
        var repair=new[]{NativeStack.New("iron_pickaxe"),NativeStack.New("iron_pickaxe"),new NativeStack(),new NativeStack()};repair[0].Damage=200;repair[1].Damage=200;Check(NativeRecipes.Result(repair,2).Damage==138,"Crafting repair includes five percent maximum durability bonus");
        var leather=NativeStack.New("leather_chestplate");leather.Data["CustomModelData"]=17;var dyed=NativeRecipes.Result(new[]{leather,NativeStack.New("red_dye"),new NativeStack(),new NativeStack()},2);Check(dyed.Id==leather.Id&&dyed.Data["display"]?["color"]!=null&&(int)dyed.Data["CustomModelData"]==17,"Leather dye preserves unrelated item NBT");
        var tipped=NativeInventory.Empty(9);for(int i=0;i<9;i++)tipped[i]=NativeStack.New("arrow");tipped[4]=NativeStack.New("lingering_potion");tipped[4].Data["Potion"]="minecraft:strong_poison";var arrows=NativeRecipes.Result(tipped,3);Check(arrows.Count==8&&arrows.Id=="minecraft:tipped_arrow"&&(string)arrows.Data["Potion"]=="minecraft:strong_poison","Tipped arrow crafting carries the potion payload");
        var written=NativeStack.New("written_book");written.Data["pages"]=new JArray("page");written.Data["generation"]=1;var books=NativeRecipes.Result(new[]{written,NativeStack.New("writable_book"),new NativeStack(),new NativeStack()},2);Check(books.Count==1&&(int)books.Data["generation"]==2&&NativeRecipes.SpecialRemainders(new[]{written})[0].Id==written.Id,"Book copies increment generation while retaining the original");written.Data["generation"]=2;Check(NativeRecipes.Result(new[]{written,NativeStack.New("writable_book"),new NativeStack(),new NativeStack()},2).Empty,"Copies of copies cannot clone further");
        var rocket=NativeRecipes.Result(new[]{NativeStack.New("paper"),NativeStack.New("gunpowder"),NativeStack.New("gunpowder"),new NativeStack()},2);Check(rocket.Count==3&&(int)rocket.Data["Fireworks"]["Flight"]==2,"Rocket crafting records its flight strength");
        var pick=NativeStack.New("diamond_pickaxe");pick.Data["silk_touch"]=1;var stone=NativeRoom.Cell(0,0,"stone");Check(NativeLoot.RollBlock(stone,pick,new Random(2)).Single().Id=="minecraft:stone","Block loot recognizes Silk Touch");pick.Data.Remove("silk_touch");Check(NativeLoot.RollBlock(stone,pick,new Random(2)).Single().Id=="minecraft:cobblestone","Ordinary stone mining uses its vanilla loot alternative");
        var custom=NativeStack.New("potion");custom.Data["CustomPotionEffects"]=new JArray(new JObject{["Id"]=1,["Duration"]=120,["Amplifier"]=1});Check(NativeData.PotionEffects(custom).Any(e=>(string)e["id"]=="minecraft:speed"&&(int)e["amplifier"]==1),"Custom potion NBT resolves numeric Java effect identifiers");
        using(var game=WorldCase(root,assets,"path")){var r=CurrentRoom(game);for(int bx=-4;bx<9;bx++)Put(r,bx,0,"stone");Put(r,1,1,"stone");var mob=new JObject{["entity"]=1,["kind"]="minecraft:zombie",["x"]=.5,["y"]=1,["width"]=.6,["height"]=1.8};var path=(JArray)typeof(NativeGame).GetMethod("FindPath",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(game,new object[]{mob,4.5,1.0});Check(path.Count>0&&path.Any(p=>(double)p[1]>=2),"Walker path steps onto a one block obstacle");Put(r,1,2,"bedrock");Put(r,1,3,"bedrock");path=(JArray)typeof(NativeGame).GetMethod("FindPath",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(game,new object[]{mob,4.5,1.0});Check(!path.Any(p=>(double)p[0]>1),"Walker cannot plan through an impassable wall");}
    }
}
